//! The general pasteboard, as seen by the watcher and the paster.

use std::fmt;

use super::PlatformError;

/// Plain text, UTF-8.
pub const UTI_PLAIN_TEXT: &str = "public.utf8-plain-text";
/// Carried by every write Tadidy makes, so the watcher does not record it as a new clip.
pub const UTI_TADIDY_MARKER: &str = "app.tadidy.internal";
/// Types that mark a copy as not meant for a history (password managers, transient data).
pub const IGNORED_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// One data format of a clip, identified by its UTI.
#[derive(Clone, PartialEq, Eq)]
pub struct Representation {
    pub uti: String,
    pub data: Vec<u8>,
}

impl Representation {
    pub fn new(uti: impl Into<String>, data: impl Into<Vec<u8>>) -> Self {
        Self {
            uti: uti.into(),
            data: data.into(),
        }
    }
}

// Printed by hand: a derived `Debug` would put the clip's bytes in a log or a test failure.
impl fmt::Debug for Representation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Representation")
            .field("uti", &self.uti)
            .field("len", &self.data.len())
            .finish()
    }
}

/// `NSPasteboard.generalPasteboard`. Only the first pasteboard item is read for now.
pub trait Pasteboard: Send + Sync {
    /// Grows by at least one every time the pasteboard's content changes.
    fn change_count(&self) -> i64;
    /// The UTIs of the current content.
    fn types(&self) -> Vec<String>;
    /// The bytes of one representation, `None` when the type is not on the pasteboard.
    fn read(&self, uti: &str) -> Option<Vec<u8>>;
    /// Clears the pasteboard, writes every item in one pasteboard item and returns the new
    /// change count.
    fn write(&self, items: &[Representation]) -> Result<i64, PlatformError>;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn debug_prints_the_uti_and_the_length_never_the_data() {
        let representation = Representation::new(UTI_PLAIN_TEXT, b"hunter2".to_vec());

        let printed = format!("{representation:?}");

        assert!(printed.contains(UTI_PLAIN_TEXT));
        assert!(printed.contains('7'));
        assert!(!printed.contains("hunter2"));
        assert!(!printed.contains("104"));
    }
}
